
import { IMAGE_URL } from "src/utils/config"



const ImageUpload = ({ value, onChange, className }) => {

  const handleUploadedFile = (e) => {
    onChange(e)
  }
  return (
    <label
      style={{ border: "1px solid #d3d6d8", borderRadius: "8px", display: "flex", justifyContent: "center", alignItems: "center", width: "100px", height: "100px" }}
      className={className}>
      {
        value ?
          (typeof value === 'string' ?
            <img src={`${IMAGE_URL}${value}`} alt="" className="" />
            :
            <img src={URL.createObjectURL(value)} alt="" className="" />
          )
          :
          "+"
      }
      <input type="file" style={{ display: "none" }} accept=".png,.jpg,.jpeg" onChange={handleUploadedFile} />
    </label>
  )
}

export default ImageUpload