  const handleFileChange = (e, index) => {
    const fileInput = e.target;
    const file = fileInput.files[0];
    const updatedIcons = [...pwaIcons];

    if (file) {
      if (file.type === "image/png") {
        updatedIcons[index] = {
          ...updatedIcons[index],
          src: URL.createObjectURL(file),
          file,
          sizes: `${file.width}x${file.height}`,
        };
        updatedIcons[index].purpose = index === 0 ? 'maskable' : 'any';

        setPWAIcons(updatedIcons);
      } else {
        GenerateToastConfig("Please select a PNG file");
      }
    }
  };

