import React, { useEffect, useState } from 'react';
import Modal from '@mui/material/Modal';
import { Button, FormControl, InputLabel, MenuItem, Select, TextField, Typography } from '@mui/material';
import { useMyContext } from '../provider';
import useResponsive from '../../hooks/useResponsive';


// eslint-disable-next-line react/prop-types
function AddCurrencyModal({ open, handleClose, onAddCurrency }) {
  const [currencies, setCurrencies] = useState({});
  const [selectedCurrency, setSelectedCurrency] = useState('');
  const [currencyName, setCurrencyName] = useState('');
  const {i18} = useMyContext();
  const isMobile = useResponsive("down", "sm");

  useEffect(() => {
    fetchCurrencies();
  }, []);

  const fetchCurrencies = async () => {
    try {
      const response = await fetch('https://openexchangerates.org/api/currencies.json');
      const data = await response.json();
      setCurrencies(data); // Set the currencies object
    } catch (error) {
      console.error('Error fetching currencies:', error);
    }
  };

  const handleCurrencyChange = (event) => {
    const selectedCurrencyCode = event.target.value;
    setSelectedCurrency(selectedCurrencyCode);
    // Fetch the currency name corresponding to the selected currency code
    const currencyName = currencies[selectedCurrencyCode];
    setCurrencyName(currencyName);
  };

  const handleValueChange = (event) => {
    setCurrencyName(event.target.value);
  };



  const handleSubmitCurrency = async (event) => {
    event.preventDefault();

    try {
      const formData = new FormData(event.target);
      const code = formData.get("code");
      const currencyName = formData.get("currencyName");

      // Pass the currency data to the callback function
      onAddCurrency({ code, currencyName });

      // Close the modal
      handleClose();
      setSelectedCurrency("")
      setCurrencyName("")
    } catch (error) {
      console.error('Error submitting currency:', error);
    }
  };


  return (
    <Modal
      open={open}
      onClose={handleClose}
      aria-labelledby="add-currency-modal"
      aria-describedby="add-currency-form"
      centered
    >
      <form onSubmit={handleSubmitCurrency}>
        <div
          style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: isMobile ? "90%" : 400,
            backgroundColor: 'white',
            borderRadius: '8px',
            padding: '24px',
            boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
          }}
        >
          <Typography variant="h5" align="center" gutterBottom>
          {i18?.SETTINGSLIST?.ADD_CURRENCY || "#Add Currency"}
          </Typography>
          <FormControl fullWidth sx={{ my: 1 }}>
          <InputLabel id="currency-select-label">{i18?.SETTINGSLIST?.SELECT_CURRENCY || "#Select Currency"}</InputLabel>
            <Select
              name="code"
              labelId="currency-select-label"
              id="currency-select"
              value={selectedCurrency}
              onChange={handleCurrencyChange}
              label="Select Currency"
            >
              {Object.keys(currencies).map((currencyCode) => (
                <MenuItem key={currencyCode} value={currencyCode}>
                  {currencyCode} - {currencies[currencyCode]}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <TextField
            fullWidth
            id="currency-name"
            name="currencyName"
            label={i18?.SETTINGSLIST?.CURRENCY_NAME || "#Currency Name"}
            value={currencyName}
            onChange={handleValueChange}
            variant="outlined"
            sx={{ my: 1 }}
          />
          {/* <Button fullWidth variant="contained" onClick={handleAddCurrency} sx={{ mt: 2 }}>
            Add Currency
          </Button> */}
          <Button fullWidth variant="contained" type="submit" sx={{ mt: 2 }}>
          {i18?.SETTINGSLIST?.ADD_CURRENCY || "#Add Currency"}
          </Button>
        </div>
      </form>
    </Modal>
  );
}

export default AddCurrencyModal;
