export const replaceStarsInMobileNumber = (number, sensitive) => {
   const envValue = sensitive;
   if (number) {
      if (envValue === "1") {
         const fristPart = number.substring(0, 2);
         const lastTwo = number.slice(-2)
         const maskedPart = number.substring(3).replace(/\d/g, '*');
         return fristPart + maskedPart + lastTwo;
      }
   }
   return (number)
}

export const replaceStarsInEmailAddress = (email, sensitive = 0, val) => {
   const envValue = sensitive;
// console.log("envValue",envValue)
   let hiddenEmail = email;

   if (email && envValue === "1" && email.includes("@")) {
      const parts = email.split('@');
      const part2 = parts[1].split('.')
      const hiddenLocalPart = `${parts[0].substring(0, Math.min(2, parts[0].length))}****`;
      const secondPart = `${part2[0].substring(0, Math.min(0, part2[0].length))}`;
      hiddenEmail = `${hiddenLocalPart}@${`${secondPart}.${part2[1]}`}`;
   } else {
      return val
   }

   return hiddenEmail;
}

export const replaceAPIkey = (key, sensitive, val) => {
   const envValue = sensitive;
   let hiddenKey = key;

   if (key && envValue === "1") {
      const firstTen = key.slice(0, 5);
      const lastTen = key.slice(-5);
      const middle = "*".repeat(Math.max(key.length - 10, 0));
      hiddenKey = firstTen + middle + lastTen;
   } else {
      return val
   }
   return hiddenKey;
}

export const replacePaymentAPIkey = (key, sensitive, val,middleval,slice) => {
   const envValue = sensitive;
   let hiddenKey = key;
   // debugger
   if (key && envValue === "1") {
      const firstTen = key.slice(0, (slice || 10));
      const lastTen = key.slice(( -slice || -10));
      const middle = "*".repeat(Math.max(key.length - (middleval || 20), 0));
      hiddenKey = firstTen + middle + lastTen;
   } else {
      return val
   }
   return hiddenKey;
}
 
export const capitalizeFirstLetter = (string) => {
   if (!string) return '';
   return string.charAt(0).toUpperCase() + string.slice(1).toLowerCase();
};
